package test;

public class NegativeExample {
    public void doNotMatch(String message) {
        // Not an array as the last argument, so should not match.
        System.out.println(message);
    }

    public void doNotMatchMultipleArgs(int num, String str) {
        // Neither argument is an array being passed as the last argument to a varargs method.
        myMethod(num, str);
    }

    public void myMethod(int a, String b) {}

    public void doNotMatchWhenAlreadyCasted(Object[] data) {
        // Already explicitly cast, so no change should occur (idempotent).
        java.util.Arrays.asList((java.lang.Object[]) data);
    }
}
